package com.booksyde.entity;
import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="reading_progress",schema="public",uniqueConstraints=@UniqueConstraint(columnNames={"user_id","volume_id"})) public class ReadingProgressEntity { @Id @Column(nullable=false) private UUID id; @Column(name="user_id",nullable=false) private UUID userId; @Column(name="volume_id",nullable=false) private UUID volumeId; @Column(name="page_index",nullable=false) private int pageIndex; @Column(name="completed_at") private OffsetDateTime completedAt; @Column(name="created_at",insertable=false,updatable=false) private OffsetDateTime createdAt; @Column(name="updated_at",insertable=false) private OffsetDateTime updatedAt; protected ReadingProgressEntity(){} public ReadingProgressEntity(UUID u,UUID v,int page,OffsetDateTime done){id=UUID.randomUUID();userId=u;volumeId=v;pageIndex=page;completedAt=done;} public UUID getVolumeId(){return volumeId;} public int getPageIndex(){return pageIndex;} public OffsetDateTime getCompletedAt(){return completedAt;} public OffsetDateTime getUpdatedAt(){return updatedAt;} public void update(int page,OffsetDateTime done){pageIndex=page;completedAt=done;updatedAt=OffsetDateTime.now();}}